import { createReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { StorageObjectMissingError } from './errors.js';

/**
 * Stores objects as files under one directory. For local development only: most hosts
 * (including Render) wipe the disk on every deploy, so production must use S3.
 */
export function createLocalStorage(directory) {
  const root = path.resolve(directory);

  // Keys are generated by the server, but resolve defensively so nothing can ever escape `root`.
  function resolveKey(key) {
    const target = path.resolve(root, key);
    if (!target.startsWith(root + path.sep)) throw new Error('Invalid storage key');
    return target;
  }

  return {
    async put(key, buffer) {
      const target = resolveKey(key);
      await mkdir(path.dirname(target), { recursive: true });
      await writeFile(target, buffer);
    },
    async getStream(key) {
      const target = resolveKey(key);
      try {
        await stat(target);
      } catch (error) {
        if (error.code === 'ENOENT') throw new StorageObjectMissingError(key);
        throw error;
      }
      return createReadStream(target);
    },
    async remove(key) {
      await rm(resolveKey(key), { force: true });
    },
  };
}
